using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Measurements;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Temporal;
namespace Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Temporal;
public sealed class AstronomyTemporalReferenceContextValidationRule:TemporalRuleBase{public const string Id="temporal.reference-context.compatibility"; public override string RuleId=>Id; public override int Order=>200; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyTemporalPatternPayload p,AstronomyKnowledgeValidationContext c){var r=p.Pattern.ReferenceContext; var ok=r.Basis switch{AstronomyTemporalReferenceBasis.Utc=>r.Entity is null&&r.Epoch is null&&r.ObservationContext is null, AstronomyTemporalReferenceBasis.EpochRelative=>r.Epoch is not null, AstronomyTemporalReferenceBasis.EntityRelative=>r.Entity is not null, AstronomyTemporalReferenceBasis.ObserverRelative=>r.ObservationContext is not null, _=>true}; if(!ok) yield return Issue(AstronomyTemporalValidationCodes.ReferenceContextIncompatible,"Temporal reference basis is incompatible with supplied context.","$.pattern.referenceContext",RuleId);}}
